#define PI 3.1415926535897932384626433832795

// WAVE DRAWING FUNCTION
vec4 wave(vec2 uv, float thic, float xoff, float yoff, float freq, float amp, float blur, float speed, vec3 colour) {
    return vec4(
        colour, 
        smoothstep(
            .1 / iResolution.y, 
            -abs(uv.x * blur), 
            abs(yoff + (amp/2. * cos(uv.x * freq * PI + (iTime * speed) + xoff)) - uv.y) - thic)
    );
}

// CIRCLE FUNCTION
vec4 circle(vec2 uv, vec2 pos, float rad, vec3 col, float smt) {
    float value = distance(pos, uv);

    if (smt > 1.0) // Smooth edges mode
        value = smoothstep(value, value + smt, rad);
    else     // Hard edges mode
        value = step(value, rad);

    return vec4(col, value);
}

// RING FUNCTION
vec4 ring(vec2 uv, vec2 pos, float rad, vec3 col, float thic) {
    float value = distance(pos, uv);
    value = step(value, rad) - step(value + thic, rad);
    return vec4(col, value);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Aspect Ratio Fix
    uv = uv * 2. - 1.;
    uv.x *= iResolution.x/iResolution.y;

    vec4 background = vec4(0.);
    vec4 foreground;

    // Colour Waves
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));
    col = col * 0.1;
    for(float i = 0.; i < 100.; i += 1.0) {
        background = mix(background, foreground, foreground.a);
        foreground = wave(
            uv,
            0.01 + i/10000.,
            0.0,
            0.75 * i/1000. + 0.5,
            i/100.,
            i/250. * tan(iTime),
            i/1000.,
            iTime/1000. * cos(iTime)/10.,
            col
        );
        col = col * 1.025;
    }

    col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));
    col = col * 0.1;
    for(float i = 0.; i < 100.; i += 1.0) {
        background = mix(background, foreground, foreground.a);
        foreground = wave(
            uv,
            0.01 + i/10000.,
            PI,
            0.75 * i/1000. - 0.5,
            i/100.,
            i/250. * tan(iTime),
            i/1000.,
            iTime/1000. * cos(iTime)/10.,
            col
        );
        col = col * 1.025;
    }

    col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));
    col = col * 0.1;
    for(float i = 0.; i < 100.; i += 1.0) {
        background = mix(background, foreground, foreground.a);
        foreground = wave(
            uv,
            0.01 + i/10000.,
            0.0,
            0.75 * i/1000. * -sin(iTime),
            i/50.,
            i/150. * cos(iTime),
            i/1000.,
            iTime/1000. * sin(iTime)/10.,
            col
        );
        col = col * 1.025;
    }

    // Circle Cutout
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        2.5,
        vec3(0.),
        1.
    );
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        0.75,
        vec3(0.),
        -0.5
    );
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        0.95,
        vec3(0.),
        -0.5
    );
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        0.99,
        vec3(0.),
        -0.5
    );


    // Output to screen
    fragColor = mix(background, foreground, foreground.a);
}

